cat > .gitignore <<'EOF'
/executable
/out/
/tmp/
*.test
EOF
cat > go.mod <<'EOF'
module caesiumclt_reimpl

go 1.22
EOF
cat > main.go <<'EOF'
package main

import (
    "bytes"
    "encoding/binary"
    "errors"
    "fmt"
    "image"
    "image/color"
    "image/gif"
    "image/jpeg"
    "image/png"
    _ "image/gif"
    _ "image/jpeg"
    _ "image/png"
    "io"
    "math"
    "os"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
    "time"
)

type Options struct {
    QualitySet bool
    Quality int
    Lossless bool
    MaxSizeSet bool
    MaxSize int64
    WidthSet bool
    Width int
    HeightSet bool
    Height int
    LongSet bool
    LongEdge int
    ShortSet bool
    ShortEdge int
    NoUpscale bool
    OutputSet bool
    Output string
    SameFolder bool
    Format string
    FormatSet bool
    PNGOpt int
    JPEGSubsampling string
    JPEGBaseline bool
    Zopfli bool
    Exif bool
    KeepDates bool
    StripICC bool
    Suffix string
    Recursive bool
    KeepStructure bool
    DryRun bool
    Threads uint64
    Overwrite string
    MinSavingsSet bool
    MinSavings MinSaving
    Quiet bool
    Verbose int
    Files []string

    compName string
    destName string
    resizeNames []string
}

type MinSaving struct { IsPercent bool; Percent float64; Bytes int64; Display string }

type ImgInfo struct { Path string; Format string; Width int; Height int; Size int64; InputRoot string }

type Result struct { Src, Dst string; InSize, OutSize int64; Status string; Message string }

func main() {
    opts, code := parseArgs(os.Args[1:])
    if code >= 0 { os.Exit(code) }
    code = run(opts)
    os.Exit(code)
}

func parseArgs(args []string) (*Options, int) {
    opts := &Options{Format:"original", PNGOpt:3, JPEGSubsampling:"auto", Overwrite:"all", Verbose:1}
    setOnce := map[string]bool{}
    needValue := func(name, display string, i *int, cur, attached string) (string, bool) {
        if setOnce[display] { parserError(fmt.Sprintf("error: the argument '%s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\nFor more information, try '--help'.\n", display)); return "", false }
        setOnce[display]=true
        if attached != "" { return attached, true }
        if *i+1 >= len(args) || strings.HasPrefix(args[*i+1], "-") {
            parserError(fmt.Sprintf("error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n", display)); return "", false
        }
        *i++
        return args[*i], true
    }
    for i:=0; i<len(args); i++ {
        a:=args[i]
        if a=="--" { opts.Files=append(opts.Files,args[i+1:]...); break }
        if a=="-h" { printShortHelp(); return nil,0 }
        if a=="--help" { printLongHelp(); return nil,0 }
        if a=="-V" || a=="--version" { fmt.Println("caesiumclt 1.3.0"); return nil,0 }
        if strings.HasPrefix(a,"--") {
            name:=a; val:=""
            if eq:=strings.Index(a,"="); eq>=0 { name=a[:eq]; val=a[eq+1:] }
            switch name {
            case "--quality":
                v,ok:=needValue(name,"--quality <QUALITY>",&i,a,val); if !ok { return nil,2 }
                q,err:=parseQuality(v); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--quality <QUALITY>': %s\n\nFor more information, try '--help'.\n", v, err.Error())); return nil,2 }
                opts.QualitySet=true; opts.Quality=q; opts.compName="--quality <QUALITY>"
            case "--lossless": if setOnce["--lossless"] { multi("--lossless"); return nil,2 }; setOnce["--lossless"]=true; opts.Lossless=true; opts.compName="--lossless"
            case "--max-size":
                v,ok:=needValue(name,"--max-size <MAX_SIZE>",&i,a,val); if !ok { return nil,2 }
                n,err:=parseByteSize(v); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--max-size <MAX_SIZE>': Invalid size format: couldn't parse %q into a ByteSize, cannot parse float from empty string\n\nFor more information, try '--help'.\n", v, v)); return nil,2 }
                opts.MaxSizeSet=true; opts.MaxSize=n; opts.compName="--max-size <MAX_SIZE>"
            case "--width":
                v,ok:=needValue(name,"--width <WIDTH>",&i,a,val); if !ok { return nil,2 }; n,err:=strconv.ParseUint(v,10,0); if err!=nil { invalidDigit(v,"--width <WIDTH>",err); return nil,2 }; opts.WidthSet=true; opts.Width=int(n); opts.resizeNames=append(opts.resizeNames,"--width <WIDTH>")
            case "--height":
                v,ok:=needValue(name,"--height <HEIGHT>",&i,a,val); if !ok { return nil,2 }; n,err:=strconv.ParseUint(v,10,0); if err!=nil { invalidDigit(v,"--height <HEIGHT>",err); return nil,2 }; opts.HeightSet=true; opts.Height=int(n); opts.resizeNames=append(opts.resizeNames,"--height <HEIGHT>")
            case "--long-edge":
                v,ok:=needValue(name,"--long-edge <LONG_EDGE>",&i,a,val); if !ok { return nil,2 }; n,err:=strconv.ParseUint(v,10,0); if err!=nil { invalidDigit(v,"--long-edge <LONG_EDGE>",err); return nil,2 }; opts.LongSet=true; opts.LongEdge=int(n); opts.resizeNames=append(opts.resizeNames,"--long-edge <LONG_EDGE>")
            case "--short-edge":
                v,ok:=needValue(name,"--short-edge <SHORT_EDGE>",&i,a,val); if !ok { return nil,2 }; n,err:=strconv.ParseUint(v,10,0); if err!=nil { invalidDigit(v,"--short-edge <SHORT_EDGE>",err); return nil,2 }; opts.ShortSet=true; opts.ShortEdge=int(n); opts.resizeNames=append(opts.resizeNames,"--short-edge <SHORT_EDGE>")
            case "--no-upscale": opts.NoUpscale=true
            case "--output":
                v,ok:=needValue(name,"--output <OUTPUT>",&i,a,val); if !ok { return nil,2 }; opts.OutputSet=true; opts.Output=v; opts.destName="--output <OUTPUT>"
            case "--same-folder-as-input": opts.SameFolder=true; opts.destName="--same-folder-as-input"
            case "--format":
                v,ok:=needValue(name,"--format <FORMAT>",&i,a,val); if !ok { return nil,2 }; if !oneOf(v,[]string{"jpeg","png","gif","webp","tiff","original"}) { parserError(fmt.Sprintf("error: invalid value '%s' for '--format <FORMAT>'\n  [possible values: jpeg, png, gif, webp, tiff, original]\n\nFor more information, try '--help'.\n",v)); return nil,2 }; opts.Format=v; opts.FormatSet=true
            case "--png-opt-level":
                v,ok:=needValue(name,"--png-opt-level <PNG_OPT_LEVEL>",&i,a,val); if !ok { return nil,2 }; n,err:=parseSmallNum(v); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--png-opt-level <PNG_OPT_LEVEL>': '%s' is not a valid number\n\nFor more information, try '--help'.\n",v,v)); return nil,2 }; if n>6 { parserError(fmt.Sprintf("error: invalid value '%s' for '--png-opt-level <PNG_OPT_LEVEL>': PNG optimization level must be between 0 and 6, but got %d\n\nFor more information, try '--help'.\n",v,n)); return nil,2 }; opts.PNGOpt=n
            case "--jpeg-chroma-subsampling":
                v,ok:=needValue(name,"--jpeg-chroma-subsampling <JPEG_CHROMA_SUBSAMPLING>",&i,a,val); if !ok { return nil,2 }; if !oneOf(v,[]string{"4:4:4","4:2:2","4:2:0","4:1:1","auto"}) { parserError(fmt.Sprintf("error: invalid value '%s' for '--jpeg-chroma-subsampling <JPEG_CHROMA_SUBSAMPLING>'\n  [possible values: 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto]\n\nFor more information, try '--help'.\n",v)); return nil,2 }; opts.JPEGSubsampling=v
            case "--jpeg-baseline": opts.JPEGBaseline=true
            case "--zopfli": opts.Zopfli=true
            case "--exif": opts.Exif=true
            case "--keep-dates": opts.KeepDates=true
            case "--strip-icc": opts.StripICC=true
            case "--suffix": v,ok:=needValue(name,"--suffix <SUFFIX>",&i,a,val); if !ok { return nil,2 }; opts.Suffix=v
            case "--recursive": opts.Recursive=true
            case "--keep-structure": opts.KeepStructure=true
            case "--dry-run": opts.DryRun=true
            case "--threads": v,ok:=needValue(name,"--threads <THREADS>",&i,a,val); if !ok { return nil,2 }; n,err:=strconv.ParseUint(v,10,64); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--threads <THREADS>': invalid digit found in string\n\nFor more information, try '--help'.\n",v)); return nil,2 }; opts.Threads=n
            case "--overwrite": v,ok:=needValue(name,"--overwrite <OVERWRITE>",&i,a,val); if !ok { return nil,2 }; if !oneOf(v,[]string{"all","never","bigger"}) { parserError(fmt.Sprintf("error: invalid value '%s' for '--overwrite <OVERWRITE>'\n  [possible values: all, never, bigger]\n\nFor more information, try '--help'.\n",v)); return nil,2 }; opts.Overwrite=v
            case "--min-savings": v,ok:=needValue(name,"--min-savings <MIN_SAVINGS>",&i,a,val); if !ok { return nil,2 }; ms,err:=parseMinSaving(v); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--min-savings <MIN_SAVINGS>': Invalid size format: '%s'. Use percentage (e.g., '10%%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes\n\nFor more information, try '--help'.\n",v,v)); return nil,2 }; opts.MinSavingsSet=true; opts.MinSavings=ms
            case "--quiet": opts.Quiet=true
            case "--verbose": v,ok:=needValue(name,"--verbose <VERBOSE>",&i,a,val); if !ok { return nil,2 }; n,err:=parseSmallNum(v); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--verbose <VERBOSE>': '%s' is not a valid number\n\nFor more information, try '--help'.\n",v,v)); return nil,2 }; if n>3 { parserError(fmt.Sprintf("error: invalid value '%s' for '--verbose <VERBOSE>': Verbosity must be between 0 and 3, but got %d\n\nFor more information, try '--help'.\n",v,n)); return nil,2 }; opts.Verbose=n
            default: unexpected(a); return nil,2
            }
        } else if strings.HasPrefix(a,"-") && a != "-" {
            if len(a)>2 {
                consumed:=false
                for j:=1; j<len(a); j++ {
                    ch:=a[j]
                    switch ch {
                    case 'R': opts.Recursive=true
                    case 'S': opts.KeepStructure=true
                    case 'd': opts.DryRun=true
                    case 'Q': opts.Quiet=true
                    case 'e': opts.Exif=true
                    case 'q','o','O':
                        attached:=a[j+1:]
                        if strings.HasPrefix(attached,"=") { attached=attached[1:] }
                        disp:=map[byte]string{'q':"--quality <QUALITY>",'o':"--output <OUTPUT>",'O':"--overwrite <OVERWRITE>"}[ch]
                        v,ok:=needValue("",disp,&i,a,attached); if !ok { return nil,2 }
                        if ch=='q' { q,err:=parseQuality(v); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--quality <QUALITY>': %s\n\nFor more information, try '--help'.\n", v, err.Error())); return nil,2 }; opts.QualitySet=true; opts.Quality=q; opts.compName="--quality <QUALITY>" }
                        if ch=='o' { opts.OutputSet=true; opts.Output=v; opts.destName="--output <OUTPUT>" }
                        if ch=='O' { if !oneOf(v,[]string{"all","never","bigger"}) { parserError(fmt.Sprintf("error: invalid value '%s' for '--overwrite <OVERWRITE>'\n  [possible values: all, never, bigger]\n\nFor more information, try '--help'.\n",v)); return nil,2 }; opts.Overwrite=v }
                        consumed=true
                    default: unexpected("-"+string(ch)); return nil,2
                    }
                    if consumed { break }
                }
            } else {
                switch a {
                case "-q": v,ok:=needValue("","--quality <QUALITY>",&i,a,""); if !ok { return nil,2 }; q,err:=parseQuality(v); if err!=nil { parserError(fmt.Sprintf("error: invalid value '%s' for '--quality <QUALITY>': %s\n\nFor more information, try '--help'.\n", v, err.Error())); return nil,2 }; opts.QualitySet=true; opts.Quality=q; opts.compName="--quality <QUALITY>"
                case "-o": v,ok:=needValue("","--output <OUTPUT>",&i,a,""); if !ok { return nil,2 }; opts.OutputSet=true; opts.Output=v; opts.destName="--output <OUTPUT>"
                case "-O": v,ok:=needValue("","--overwrite <OVERWRITE>",&i,a,""); if !ok { return nil,2 }; if !oneOf(v,[]string{"all","never","bigger"}) { parserError(fmt.Sprintf("error: invalid value '%s' for '--overwrite <OVERWRITE>'\n  [possible values: all, never, bigger]\n\nFor more information, try '--help'.\n",v)); return nil,2 }; opts.Overwrite=v
                case "-R": opts.Recursive=true
                case "-S": opts.KeepStructure=true
                case "-d": opts.DryRun=true
                case "-Q": opts.Quiet=true
                case "-e": opts.Exif=true
                default: unexpected(a); return nil,2
                }
            }
        } else { opts.Files=append(opts.Files,a) }
    }
    if code:=checkConflicts(opts); code!=0 { return nil,code }
    return opts,-1
}

func checkConflicts(o *Options) int {
    comps:=[]string{}
    if o.QualitySet { comps=append(comps,"--quality <QUALITY>") }
    if o.Lossless { comps=append(comps,"--lossless") }
    if o.MaxSizeSet { comps=append(comps,"--max-size <MAX_SIZE>") }
    if len(comps)>1 { parserError(fmt.Sprintf("error: the argument '%s' cannot be used with '%s'\n\nUsage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> <FILES>...\n\nFor more information, try '--help'.\n", comps[0], comps[1])); return 2 }
    if o.OutputSet && o.SameFolder { parserError("error: the argument '--output <OUTPUT>' cannot be used with '--same-folder-as-input'\n\nUsage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> <FILES>...\n\nFor more information, try '--help'.\n"); return 2 }
    if o.WidthSet && o.LongSet { conflict("--width <WIDTH>","--long-edge <LONG_EDGE>"); return 2 }
    if o.WidthSet && o.ShortSet { conflict("--width <WIDTH>","--short-edge <SHORT_EDGE>"); return 2 }
    if o.HeightSet && o.LongSet { conflict("--height <HEIGHT>","--long-edge <LONG_EDGE>"); return 2 }
    if o.HeightSet && o.ShortSet { conflict("--height <HEIGHT>","--short-edge <SHORT_EDGE>"); return 2 }
    if o.LongSet && o.ShortSet { conflict("--long-edge <LONG_EDGE>","--short-edge <SHORT_EDGE>"); return 2 }
    missing:=[]string{}
    if len(comps)==0 { missing=append(missing,"<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>") }
    if !o.OutputSet && !o.SameFolder { missing=append(missing,"<--output <OUTPUT>|--same-folder-as-input>") }
    if len(missing)>0 {
        filesPart := "[FILES]..."; if len(o.Files)>0 { filesPart="<FILES>..." }
        fmt.Fprintln(os.Stderr,"error: the following required arguments were not provided:")
        for _,m:= range missing { fmt.Fprintln(os.Stderr,"  "+m) }
        fmt.Fprintf(os.Stderr,"\nUsage: executable <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> %s\n\nFor more information, try '--help'.\n", filesPart)
        return 2
    }
    if o.Quiet { o.Verbose=0 }
    return 0
}

func parserError(s string){ fmt.Fprint(os.Stderr,s) }
func multi(arg string){ parserError(fmt.Sprintf("error: the argument '%s' cannot be used multiple times\n\nUsage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\nFor more information, try '--help'.\n",arg)) }
func invalidDigit(v,opt string,err error){ parserError(fmt.Sprintf("error: invalid value '%s' for '%s': invalid digit found in string\n\nFor more information, try '--help'.\n",v,opt)) }
func unexpected(a string){ parserError(fmt.Sprintf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> [FILES]...\n\nFor more information, try '--help'.\n",a,a,a)) }
func conflict(a,b string){ parserError(fmt.Sprintf("error: the argument '%s' cannot be used with '%s'\n\nUsage: executable %s <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input> <FILES>...\n\nFor more information, try '--help'.\n",a,b,a)) }
func oneOf(v string, arr []string) bool { for _,x:=range arr { if v==x { return true } }; return false }

func parseSmallNum(v string)(int,error){ n,err:=strconv.Atoi(v); if err!=nil || n<0 { return 0,err }; return n,nil }
func parseQuality(v string)(int,error){ n,err:=strconv.Atoi(v); if err!=nil { return 0,fmt.Errorf("'%s' is not a valid number",v) }; if n<0 || n>100 { return 0,fmt.Errorf("Quality must be between 0 and 100, but got %d",n) }; return n,nil }
func parseByteSize(s string)(int64,error){
    if s=="" { return 0,errors.New("bad") }
    up:=strings.ToUpper(strings.TrimSpace(s)); mult:=float64(1); num:=up
    units:=[]struct{u string;m float64}{{"KIB",1024},{"MIB",1024*1024},{"GIB",1024*1024*1024},{"KB",1000},{"MB",1000*1000},{"GB",1000*1000*1000},{"B",1}}
    for _,x:=range units { if strings.HasSuffix(up,x.u) { mult=x.m; num=strings.TrimSpace(up[:len(up)-len(x.u)]); break } }
    f,err:=strconv.ParseFloat(num,64); if err!=nil { return 0,err }
    if f<0 { return 0,errors.New("bad") }
    return int64(f*mult),nil
}
func parseMinSaving(s string)(MinSaving,error){
    if strings.HasSuffix(s,"%") { f,err:=strconv.ParseFloat(strings.TrimSuffix(s,"%"),64); if err!=nil { return MinSaving{},err }; return MinSaving{IsPercent:true,Percent:f,Display:fmt.Sprintf("%.2f%%",f)},nil }
    b,err:=parseByteSize(s); if err!=nil { return MinSaving{},err }; return MinSaving{Bytes:b,Display:humanBytes(b)},nil
}

func run(o *Options) int {
    if len(o.Files)==0 { if o.Verbose>0 { fmt.Fprintln(os.Stderr,"No files to compress") }; return 0 }
    infos, base := discover(o)
    if len(infos)==0 || base=="" { if o.Verbose>0 { fmt.Fprintln(os.Stderr,"Unable to compute the base path for the files.") }; return 255 }
    results:=[]Result{}
    for _,info:= range infos { r:=processOne(o, info, base); results=append(results,r); printResult(o,r) }
    var inTot,outTot int64; success,skip,errs:=0,0,0
    for _,r:= range results { inTot+=r.InSize; outTot+=r.OutSize; switch r.Status { case "success": success++; case "skipped": skip++; case "error": errs++ } }
    if o.Verbose>0 {
        fmt.Printf("Compressed %d files (%d success, %d skipped, %d errors)\n",len(results),success,skip,errs)
        fmt.Println(formatChange(inTot,outTot))
    }
    return 0
}

func discover(o *Options)([]ImgInfo,string){
    var infos []ImgInfo
    var baseCandidates []string
    for _,p:= range o.Files {
        st,err:=os.Stat(p); if err!=nil { continue }
        abs,_:=filepath.Abs(p)
        if st.IsDir() {
            if len(o.Files)==1 { baseCandidates=append(baseCandidates, abs) } else { baseCandidates=append(baseCandidates, filepath.Dir(abs)) }
            if o.Recursive {
                filepath.WalkDir(p, func(path string, d os.DirEntry, err error) error { if err!=nil || d.IsDir(){ return nil }; if inf,ok:=makeInfo(path, abs); ok { infos=append(infos,inf) }; return nil })
            } else {
                entries,_:=os.ReadDir(p); sort.Slice(entries,func(i,j int)bool{return entries[i].Name()<entries[j].Name()})
                for _,e:= range entries { if e.IsDir(){continue}; path:=filepath.Join(p,e.Name()); if inf,ok:=makeInfo(path, abs); ok { infos=append(infos,inf) } }
            }
        } else {
            baseCandidates=append(baseCandidates, filepath.Dir(abs))
            if inf,ok:=makeInfo(p, filepath.Dir(abs)); ok { infos=append(infos,inf) }
        }
    }
    if len(infos)==0 { return nil,"" }
    // Only consider candidates that actually contributed, approximated by common parent of valid files unless single directory root was given.
    if o.KeepStructure {
        if len(o.Files)==1 {
            st,err:=os.Stat(o.Files[0]); if err==nil && st.IsDir() { abs,_:=filepath.Abs(o.Files[0]); return infos,abs }
        }
        dirs:=[]string{}
        for _,inf:= range infos { dirs=append(dirs, filepath.Dir(absPath(inf.Path))) }
        return infos, commonPath(dirs)
    }
    if len(baseCandidates)>0 { return infos, commonPath(baseCandidates) }
    return infos, commonPath([]string{filepath.Dir(absPath(infos[0].Path))})
}
func absPath(p string) string { a,_:=filepath.Abs(p); return a }
func makeInfo(path, root string)(ImgInfo,bool){ fmt,w,h,err:=detectImage(path); if err!=nil { return ImgInfo{},false }; st,err:=os.Stat(path); if err!=nil { return ImgInfo{},false }; return ImgInfo{Path:path,Format:fmt,Width:w,Height:h,Size:st.Size(),InputRoot:root},true }
func commonPath(paths []string) string { if len(paths)==0 { return "" }; abs:=make([]string,len(paths)); for i,p:=range paths { abs[i]=filepath.Clean(p) }; c:=abs[0]; for _,p:=range abs[1:] { for !strings.HasPrefix(p+string(os.PathSeparator), c+string(os.PathSeparator)) && p!=c { nc:=filepath.Dir(c); if nc==c { return c }; c=nc } }; return c }

func detectImage(path string)(string,int,int,error){
    f,err:=os.Open(path); if err!=nil { return "",0,0,err }; defer f.Close()
    head:=make([]byte,64); n,_:=f.Read(head); head=head[:n]
    f.Seek(0,0)
    if len(head)>=12 && string(head[:4])=="RIFF" && string(head[8:12])=="WEBP" { w,h,ok:=webpDim(path); if ok { return "webp",w,h,nil }; return "",0,0,errors.New("bad webp") }
    cfg,fmt,err:=image.DecodeConfig(f); if err!=nil { return "",0,0,err }
    if fmt=="jpeg" || fmt=="png" || fmt=="gif" { return fmt,cfg.Width,cfg.Height,nil }
    return "",0,0,errors.New("unsupported")
}
func webpDim(path string)(int,int,bool){ b,err:=os.ReadFile(path); if err!=nil || len(b)<30 { return 0,0,false }; if string(b[12:16])=="VP8 " && len(b)>=30 { w:=int(binary.LittleEndian.Uint16(b[26:28]) & 0x3fff); h:=int(binary.LittleEndian.Uint16(b[28:30]) & 0x3fff); return w,h,w>0&&h>0 }; if string(b[12:16])=="VP8L" && len(b)>=25 { x:=uint32(b[21])|uint32(b[22])<<8|uint32(b[23])<<16|uint32(b[24])<<24; w:=int((x&0x3fff)+1); h:=int(((x>>14)&0x3fff)+1); return w,h,true }; if string(b[12:16])=="VP8X" && len(b)>=30 { w:=1+int(uint32(b[24])|uint32(b[25])<<8|uint32(b[26])<<16); h:=1+int(uint32(b[27])|uint32(b[28])<<8|uint32(b[29])<<16); return w,h,true }; return 0,0,false }

func processOne(o *Options, inf ImgInfo, base string) Result {
    dst:=destPath(o,inf,base)
    r:=Result{Src:inf.Path,Dst:dst,InSize:inf.Size,OutSize:0,Status:"success"}
    if o.DryRun { r.OutSize=inf.Size; return r }
    if o.Overwrite=="never" { if _,err:=os.Stat(dst); err==nil { r.Status="skipped"; r.OutSize=inf.Size; r.Message="File already exists, skipped due overwrite policy"; return r } }
    if o.FormatSet && o.Format!="original" && normalizeFormat(o.Format)==normalizeFormat(inf.Format) { r.Status="error"; r.OutSize=0; r.Message="Error compressing file: Cannot convert to the same format [10407]"; return r }
    data,err:=render(o,inf)
    if err!=nil { r.Status="error"; r.Message="Error compressing file: "+err.Error(); return r }
