func normalizeFormat(f string) string { if f=="jpg" { return "jpeg" }; return f }
func destPath(o *Options, inf ImgInfo, base string) string {
    ext:=filepath.Ext(inf.Path); name:=strings.TrimSuffix(filepath.Base(inf.Path),ext)
    outFmt:=o.Format; if outFmt=="original" { outFmt=inf.Format }
    if o.FormatSet && o.Format!="original" { ext=extFor(outFmt) }
    name=name+o.Suffix+ext
    if o.SameFolder { return filepath.Join(filepath.Dir(inf.Path), name) }
    dir:=o.Output
    if o.KeepStructure { rel,err:=filepath.Rel(base, filepath.Dir(absPath(inf.Path))); if err==nil && rel!="." { dir=filepath.Join(dir,rel) } }
