}
func extFor(f string) string { switch f { case "jpeg": return ".jpg"; case "png": return ".png"; case "gif": return ".gif"; case "webp": return ".webp"; case "tiff": return ".tiff" }; return "."+f }

func render(o *Options, inf ImgInfo)([]byte,error){
    outFmt:=o.Format; if outFmt=="original" { outFmt=inf.Format }
    targetW,targetH:=resizeDims(o,inf.Width,inf.Height)
    needDecode := outFmt!="webp" && outFmt!="tiff" && (targetW!=inf.Width || targetH!=inf.Height || outFmt!=inf.Format || inf.Format=="jpeg" || inf.Format=="png")
    if (inf.Format=="webp" || inf.Format=="gif") && outFmt==inf.Format && targetW==inf.Width && targetH==inf.Height && !o.QualitySet && !o.MaxSizeSet { return os.ReadFile(inf.Path) }
    if inf.Format=="webp" { // no standard decoder; preserve bytes when possible
        if outFmt=="webp" && targetW==inf.Width && targetH==inf.Height { return os.ReadFile(inf.Path) }
        return os.ReadFile(inf.Path)
    }
    f,err:=os.Open(inf.Path); if err!=nil { return nil,err }; defer f.Close()
    img,_,err:=image.Decode(f); if err!=nil { return nil,err }
    if needDecode && (targetW!=inf.Width || targetH!=inf.Height) { if targetW<=0 || targetH<=0 { return nil,errors.New("Invalid resize dimensions [10300]") }; img=resizeNearest(img,targetW,targetH) }
    var buf bytes.Buffer
    switch outFmt {
    case "jpeg":
        q:=80; if o.QualitySet { q=o.Quality }; if o.Lossless { q=100 }; if o.MaxSizeSet { q=qualityForTarget(o.MaxSize, inf.Size) }
        err=jpeg.Encode(&buf, flatten(img), &jpeg.Options{Quality:q})
    case "png":
        level:=png.DefaultCompression; if o.PNGOpt>=4 { level=png.BestCompression } else if o.PNGOpt<=1 { level=png.BestSpeed }
        enc:=png.Encoder{CompressionLevel:level}; err=enc.Encode(&buf,img)
    case "gif":
        err=gif.Encode(&buf,img,nil)
    case "tiff":
        err=encodeTIFF(&buf,img)
    case "webp":
