func qualityForTarget(target int64, in int64) int { if target<=0 { return 1 }; ratio:=float64(target)/math.Max(1,float64(in)); q:=int(ratio*100); if q<1 { q=1 }; if q>100 { q=100 }; return q }
func resizeDims(o *Options,w,h int)(int,int){ nw,nh:=w,h; if o.WidthSet && o.HeightSet { nw=o.Width; nh=o.Height } else if o.WidthSet { nw=o.Width; nh=int(math.Round(float64(h)*float64(nw)/float64(w))) } else if o.HeightSet { nh=o.Height; nw=int(math.Round(float64(w)*float64(nh)/float64(h))) } else if o.LongSet { if w>=h { nw=o.LongEdge; nh=int(math.Round(float64(h)*float64(nw)/float64(w))) } else { nh=o.LongEdge; nw=int(math.Round(float64(w)*float64(nh)/float64(h))) } } else if o.ShortSet { if w<=h { nw=o.ShortEdge; nh=int(math.Round(float64(h)*float64(nw)/float64(w))) } else { nh=o.ShortEdge; nw=int(math.Round(float64(w)*float64(nh)/float64(h))) } }
