func resizeNearest(src image.Image,w,h int) image.Image { dst:=image.NewRGBA(image.Rect(0,0,w,h)); b:=src.Bounds(); sw,sh:=b.Dx(),b.Dy(); for y:=0;y<h;y++{ sy:=b.Min.Y + y*sh/h; for x:=0;x<w;x++{ sx:=b.Min.X + x*sw/w; dst.Set(x,y,src.At(sx,sy)) } }; return dst }
func flatten(src image.Image) image.Image { b:=src.Bounds(); dst:=image.NewRGBA(image.Rect(0,0,b.Dx(),b.Dy())); white:=color.RGBA{255,255,255,255}; for y:=0;y<b.Dy();y++{ for x:=0;x<b.Dx();x++{ dst.Set(x,y,white); r,g,bb,a:=src.At(b.Min.X+x,b.Min.Y+y).RGBA(); if a==0 { continue }; af:=float64(a)/65535; dst.Set(x,y,color.RGBA{uint8((float64(r)/257)*af + 255*(1-af)), uint8((float64(g)/257)*af + 255*(1-af)), uint8((float64(bb)/257)*af + 255*(1-af)), 255}) } }; return dst }

func encodeTIFF(w io.Writer, img image.Image) error { b:=img.Bounds(); width,height:=b.Dx(),b.Dy(); pixelBytes:=width*height*3; entries:=uint16(10); ifdStart:=uint32(8); bitsOffset:=ifdStart+2+uint32(entries)*12+4; dataOffset:=bitsOffset+6; buf:=new(bytes.Buffer); buf.Write([]byte{'I','I',42,0}); binary.Write(buf,binary.LittleEndian,ifdStart); binary.Write(buf,binary.LittleEndian,entries); writeTag:=func(tag,typ uint16,count,val uint32){ binary.Write(buf,binary.LittleEndian,tag); binary.Write(buf,binary.LittleEndian,typ); binary.Write(buf,binary.LittleEndian,count); binary.Write(buf,binary.LittleEndian,val) }; writeTag(256,4,1,uint32(width)); writeTag(257,4,1,uint32(height)); writeTag(258,3,3,bitsOffset); writeTag(259,3,1,1); writeTag(262,3,1,2); writeTag(273,4,1,dataOffset); writeTag(277,3,1,3); writeTag(278,4,1,uint32(height)); writeTag(279,4,1,uint32(pixelBytes)); writeTag(284,3,1,1); binary.Write(buf,binary.LittleEndian,uint32(0)); binary.Write(buf,binary.LittleEndian,uint16(8)); binary.Write(buf,binary.LittleEndian,uint16(8)); binary.Write(buf,binary.LittleEndian,uint16(8)); for y:=b.Min.Y;y<b.Max.Y;y++{ for x:=b.Min.X;x<b.Max.X;x++{ r,g,bb,_:=img.At(x,y).RGBA(); buf.WriteByte(uint8(r>>8)); buf.WriteByte(uint8(g>>8)); buf.WriteByte(uint8(bb>>8)) } }; _,err:=w.Write(buf.Bytes()); return err }

func printResult(o *Options,r Result){ if o.Verbose==0 { return }; show:=false; label:=""; switch r.Status { case "success": show=o.Verbose>=3; label="Success"; case "skipped": show=o.Verbose>=2; label="Skipped"; case "error": show=o.Verbose>=2; label="Error" }; if !show { return }; fmt.Printf("[%s] %s -> %s\n",label,r.Src,r.Dst); fmt.Println(formatChange(r.InSize,r.OutSize)); if r.Message!="" { fmt.Println(r.Message) }; fmt.Println() }
func humanBytes(n int64) string { sign:=""; if n<0 { sign="-"; n=-n }; if n<1024 { return fmt.Sprintf("%s%d B",sign,n) }; f:=float64(n)/1024; if f<1024 { return fmt.Sprintf("%s%.1f KiB",sign,f) }; return fmt.Sprintf("%s%.1f MiB",sign,f/1024) }
func formatChange(in,out int64) string { diff:=out-in; sign:="-"; if diff>0 { sign="+" }; abs:=diff; if abs<0 { abs=-abs }; pct:=0.0; if in>0 { pct=float64(diff)*100/float64(in) }; return fmt.Sprintf("%s -> %s [%s%s | %+0.2f%%]", humanBytes(in), humanBytes(out), sign, humanBytes(abs), pct) }

